const payload = $input.first().json;
if (!payload || payload.allSynthetic !== true || !payload.candidate || !Array.isArray(payload.jobs)) {
  throw new Error('Expected synthetic candidate and jobs from the read-only demo API.');
}
const candidate = payload.candidate;
if (!candidate.id || !Array.isArray(candidate.skills) || typeof candidate.experienceYears !== 'number') {
  throw new Error('Incomplete candidate test record');
}
return [{json:{candidate, jobs:payload.jobs, source:payload.source, allSynthetic:true}}];

const input=$input.first().json;
const levels={'high school':1,'bachelor':2,'master':3,'phd':4};
const cLevel=levels[String(input.candidate.degree||'').toLowerCase()]||0;
const eligible=[]; const excluded=[];
for (const job of input.jobs){
  const required=levels[String(job.minimumEducation||'').toLowerCase()]||0;
  if (!job.id || !Array.isArray(job.requiredSkills) || job.requiredSkills.length===0 || required===0 || cLevel===0) {
    excluded.push({jobId:job.id||'UNKNOWN',reason:'Incomplete or unknown eligibility data'});
  }else if(cLevel<required){
    excluded.push({jobId:job.id,reason:`Requires ${job.minimumEducation} education`});
  }else {
    eligible.push(job);
  }
}
return [{json:{candidate:input.candidate,eligible,excluded,allSynthetic:true}}];

const {candidate,eligible,excluded}= $input.first().json;
const normalize = s=>String(s).trim().toLowerCase();
const scores=eligible.map(job=>{
 const matched=job.requiredSkills.filter(s=>candidate.skills.some(cs=>normalize(cs)===normalize(s)));
 const missing=job.requiredSkills.filter(s=>!matched.some(m=>normalize(m)===normalize(s)));
 const skillPct=matched.length/job.requiredSkills.length;
 const minYears=Number(job.minimumExperienceYears);
 const expPct=(Number.isFinite(minYears)&&minYears>0)?Math.min(candidate.experienceYears/minYears,1):1;
 const skillPoints=40*skillPct,experiencePoints=30*expPct,educationPoints=30;
 const score=Math.round(skillPoints+experiencePoints+educationPoints);
 return {id:job.id,title:job.title,company:job.company,location:job.location,score,
  breakdown:{skills:Math.round(skillPoints),experience:Math.round(experiencePoints),education:Math.round(educationPoints)},
  matchedSkills:matched,missingSkills:missing,
  reason:`Matched ${matched.length}/${job.requiredSkills.length} listed skills; experience ${candidate.experienceYears} year(s) vs. ${job.minimumExperienceYears} requested; education eligible.`};
});
scores.sort((a,b)=>b.score-a.score||a.id.localeCompare(b.id));
// allScored: every eligible job, ranked (used by the interactive Telegram controller for one card per job).
return [{json:{candidate:{id:candidate.id,name:candidate.name},top3:scores.slice(0,3),allScored:scores,eligibleCount:scores.length,excludedCount:excluded.length,excluded,allSynthetic:true,scoringMethod:'Demo 40/30/30 skills/experience/education; not hiring probability'}}];

const x=$input.first().json;
let text=`Internship recommendations for ${x.candidate.name}

`;
if(!x.top3.length){text+='No eligible test jobs were found.
';}
else {x.top3.forEach((j,i)=>{text+=`${i+1}. ${j.title} — ${j.company}
   Fit score: ${j.score}/100
   ${j.reason}

`;});}
text+=`Eligibility exclusions: ${x.excludedCount}.
Synthetic data only. Scores are relative fit, not hiring probabilities.`;
return [{json:{...x,message:text}}];
